package nekouidaga.net.familyheartplugin.config
import nekouidaga.net.familyheartplugin.model.BuffDefinition
import org.bukkit.plugin.java.JavaPlugin
class Settings(private val p:JavaPlugin){fun reload(){p.reloadConfig();p.saveResource("messages.yml",false);p.saveResource("gui.yml",false);p.saveResource("buffs.yml",false);p.saveResource("penalties.yml",false)};fun range()=p.config.getDouble("skinship.target-range",3.0);fun econEnabled()=p.config.getBoolean("economy.enabled",false);fun cost(type:String)=p.config.getDouble("economy.${type}-cost",0.0);fun actionCooldown(a:String)=p.config.getLong("actions.$a.cooldown-seconds",p.config.getLong("skinship.default-cooldown-seconds",0));fun features(k:String)=p.config.getBoolean("features.$k",true);fun buffs():List<BuffDefinition>{val c=p.configFileAsYaml("buffs.yml")?:return emptyList();val s=c.getConfigurationSection("family-buffs")?:return emptyList();return s.getKeys(false).map{b->val x=s.getConfigurationSection(b)!!;BuffDefinition(b,x.getBoolean("enabled",false),x.getString("condition","")!!,x.getDouble("required",0.0),x.getInt("amplifier",0),x.getInt("duration",120),x.getString("effect","SPEED")!!,x.getDouble("multiplier",1.0))}}
private fun JavaPlugin.configFileAsYaml(name:String):org.bukkit.configuration.file.FileConfiguration?{val f=dataFolder.resolve(name);if(!f.exists())saveResource(name,false);return org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(f)}}
